#![forbid(unsafe_code)]

//! Generates `~/.config/foot/foot.ini` with Cherry Red & Black theme + Windows-familiar paste/copy.

pub fn emit_foot_ini() -> String {
    format!(
        "# Auto-generated by forge-conf for {} (ADR 0002)\n\
         font={}:size=11\n\
         pad=12x12\n\n\
         [colors]\n\
         alpha=0.96\n\
         background=070709\n\
         foreground=F4F4F5\n\
         selection-foreground=F4F4F5\n\
         selection-background=9B1126\n\
         regular0=18181B\n\
         regular1=9B1126\n\
         regular2=4CC38A\n\
         regular3=E5B567\n\
         regular4=3B82F6\n\
         regular5=EC4899\n\
         regular6=22D3EE\n\
         regular7=E4E4E7\n\
         bright0=52525B\n\
         bright1=C42B42\n\
         bright7=FFFFFF\n\n\
         [key-bindings]\n\
         clipboard-copy=Control+Shift+c Control+Insert\n\
         clipboard-paste=Control+v Control+Shift+v Shift+Insert\n\
         search-start=Control+f\n",
        forge_brand::NAME,
        forge_brand::FONT_MONO,
    )
}
